import { useMemo } from 'react';

import {
  COMMERCIAL_RESULTS_LINE_BAR_CHART_COLORS,
  COMMERCIAL_RESULTS_LINE_BAR_CHART_LEGEND_STYLE,
} from 'pages/pillars/ValueCreation/CommercialResults/config/lineBarChartConfig';
import { useLineBarChartDatasets } from 'pages/pillars/ValueCreation/PerformanceTool/hooks/useLineBarChartDatasets/useLineBarChartDatasets';
import { LineBarChartsSectionData } from 'pages/pillars/ValueCreation/PerformanceTool/types';

export const useCommercialResultsLineBarChartDatasets = (
  data?: LineBarChartsSectionData,
) => {
  const datasets = useLineBarChartDatasets(
    data,
    COMMERCIAL_RESULTS_LINE_BAR_CHART_COLORS,
  );

  const legendItems = useMemo(
    () =>
      datasets.legendItems.map((item) => ({
        ...item,
        ...COMMERCIAL_RESULTS_LINE_BAR_CHART_LEGEND_STYLE,
      })),
    [datasets.legendItems],
  );

  return {
    ...datasets,
    legendItems,
  };
};
